                                          source_kind, source_id
                             ORDER BY start_time DESC, statement_id DESC) = 1
)
SELECT c.workspace_id, c.warehouse_id, c.execution_status, c.error_class, c.source_kind, c.source_id,
       COUNT(*) AS statements,
       MIN(c.start_time) AS first_seen,
